   900  unsigned char JSLexer::consumeOctal(unsigned maxLen) {
   901    assert(*curCharPtr_ >= '0' && *curCharPtr_ <= '7');
   902
   903    if (strictMode_) {
   904      if (!error(
   905              SMLoc::getFromPointer(curCharPtr_ - 1),
