   909    }
   910
   911    auto res = (unsigned char)(*curCharPtr_++ - '0');
   912    while (--maxLen && *curCharPtr_ >= '0' && *curCharPtr_ <= '7')
   913      res = (res << 3) + *curCharPtr_++ - '0';
