   930          ch -= 'a' - 10;
   931        } else {
   932          if (errorOnFail) {
   933            error(SMLoc::getFromPointer(curCharPtr_), "invalid hex number");
   934          }
   935          return llvm::None;
   936        }
   937      }
   938      cp = (cp << 4) + ch;
   939      ++curCharPtr_;
