   951    // an invalid character.
   952    bool failed = false;
   953
   954    // Loop until we hit the } or eof, max out the value, or see an invalid char.
   955    uint32_t cp = 0;
   956    for (; *curCharPtr_ != '}'; ++curCharPtr_) {
   957      int ch = *curCharPtr_;
   958      if (ch >= '0' && ch <= '9') {
   959        ch -= '0';
   960      } else if (ch >= 'a' && ch <= 'f') {
   961        ch -= 'a' - 10;
   962      } else if (ch >= 'A' && ch <= 'F') {
   963        ch -= 'A' - 10;
