   977        if (!failed && errorOnFail) {
   978          error(
   979              SMLoc::getFromPointer(curCharPtr_),
   980              "invalid character in unicode codepoint escape");
   981        }
   982        failed = true;
   983        continue;
   984      }
   985      cp = (cp << 4) + ch;
